param([string]$ProjectRoot = (Split-Path -Parent $PSScriptRoot))

$ErrorActionPreference='Stop'
if([Threading.Thread]::CurrentThread.ApartmentState-ne[Threading.ApartmentState]::STA){throw'Run with powershell.exe -STA.'}
$halcon='C:\Program Files\MVTec\HALCON-20.11-Progress';$env:PATH=(Join-Path $halcon 'bin\x64-win64')+';'+$env:PATH
Add-Type -AssemblyName PresentationFramework
[Reflection.Assembly]::LoadFrom((Join-Path $halcon 'bin\dotnet35\halcondotnet.dll'))|Out-Null
$assembly=[Reflection.Assembly]::LoadFrom((Join-Path $ProjectRoot 'bin\x64\Debug\HalconWinFormsDemo.exe'))
function Assert([bool]$c,[string]$m){if(-not$c){throw $m}}
function Pump([int]$ms){$f=New-Object Windows.Threading.DispatcherFrame;$t=New-Object Windows.Threading.DispatcherTimer;$t.Interval=[TimeSpan]::FromMilliseconds($ms);$t.Add_Tick({$t.Stop();$f.Continue=$false});$t.Start();[Windows.Threading.Dispatcher]::PushFrame($f)}
$main=$assembly.GetType('HalconWinFormsDemo.MainWindow',$true);$serviceType=$assembly.GetType('HalconWinFormsDemo.Services.RecipeService',$true);$loggerType=$assembly.GetType('HalconWinFormsDemo.Services.AppLogger',$true);$kindType=$assembly.GetType('HalconWinFormsDemo.Models.VmToolKind',$true);$arrayType=$assembly.GetType('HalconWinFormsDemo.Models.VmPoint2DArray',$true);$lineType=$assembly.GetType('HalconWinFormsDemo.Models.VmLine2D',$true);$circleType=$assembly.GetType('HalconWinFormsDemo.Models.VmCircle2D',$true);$pointType=$assembly.GetType('HalconWinFormsDemo.Models.VmPoint2D',$true)
$private=[Reflection.BindingFlags]'Instance,NonPublic';$all=[Reflection.BindingFlags]'Instance,NonPublic,Public';$static=[Reflection.BindingFlags]'Static,Public'
$temp=Join-Path([IO.Path]::GetTempPath())('halcon-vm-s73-'+[Guid]::NewGuid().ToString('N'));[IO.Directory]::CreateDirectory($temp)|Out-Null
$service=$serviceType.GetConstructor([Type[]]@([string])).Invoke([object[]]@($temp.ToString()));$logger=$loggerType.GetConstructor([Type[]]@([string])).Invoke([object[]]@($temp.ToString()));$window=$main.GetConstructor($private,$null,[Type[]]@($serviceType,$loggerType),$null).Invoke([object[]]@($service,$logger))
$app=[Windows.Application]::Current;$ownsApp=$null-eq$app;if($ownsApp){$app=New-Object Windows.Application;$app.ShutdownMode=[Windows.ShutdownMode]::OnExplicitShutdown};$window.ShowInTaskbar=$false;$window.Left=-10000;$window.MinWidth=0;$window.MinHeight=0;$window.Width=1366;$window.Height=768;$window.Show();Pump 350
function F([string]$n){$v=$main.GetField($n,$all).GetValue($window);Write-Output -NoEnumerate $v}
function M([string]$n,[object[]]$p=@()){try{$main.GetMethod($n,$private).Invoke($window,$p)}catch{$e=$_.Exception;while($e.InnerException){$e=$e.InnerException};throw($n+': '+$e.Message)}}
function K([string]$n){[Enum]::Parse($kindType,$n)}
function Tool([string]$k,[string]$n){M 'CreateFlowTool' ([object[]]@((K $k),$n,$true,$null))}
function Run($t){M 'ExecuteFlowTool' ([object[]]@($t,'S73 smoke'))}
function Out($t,[string]$p){$a=[object[]]@($p,$null);if(-not$t.GetType().GetMethod('TryGetOutputValue').Invoke($t,$a)){throw"Missing output $p"};$a[1]}
function Has($t,[string]$p){$a=[object[]]@($p,$null);[bool]$t.GetType().GetMethod('TryGetOutputValue').Invoke($t,$a)}
function Points([double[]]$r,[double[]]$c,[string]$ctx){$arrayType.GetMethod('CreateImagePixel',$static).Invoke($null,[object[]]@($r,$c,$ctx))}
function Line([double]$r1,[double]$c1,[double]$r2,[double]$c2,[string]$ctx){$lineType.GetMethod('CreateImagePixel',$static).Invoke($null,[object[]]@($r1,$c1,$r2,$c2,$ctx))}
function Circle([double]$r,[double]$c,[double]$radius,[string]$ctx){$circleType.GetMethod('CreateImagePixel',$static).Invoke($null,[object[]]@($r,$c,$radius,$ctx))}
function Point([double]$r,[double]$c,[string]$ctx){$pointType.GetMethod('CreateImagePixel',$static).Invoke($null,[object[]]@($r,$c,$ctx))}
function SelectTools([object[]]$tools){(F 'FlowToolList').SelectedItems.Clear();foreach($tool in $tools){(F 'FlowToolList').SelectedItems.Add($tool)}}
function FindNavButton($root,[string]$toolId){if($root-is[Windows.Controls.Button]-and[string]$root.Tag-eq$toolId){return $root};$count=[Windows.Media.VisualTreeHelper]::GetChildrenCount($root);for($i=0;$i-lt$count;$i++){$found=FindNavButton ([Windows.Media.VisualTreeHelper]::GetChild($root,$i)) $toolId;if($null-ne$found){return $found}};return $null}
try{
  Assert ((F 'toolCatalog').Count-eq70 -and (F 'toolCatalog').Count-eq[Enum]::GetValues($kindType).Count) 'S73 compatibility catalog mismatch after S75.'
  Assert ((F 'DeveloperToolbarPanel').Children.Count-eq7) 'S73 added a permanent top command.'

  # A: responsive compact vertical flow, no forced horizontal scroll, preserved manual coordinates, thin state navigator.
  $flow=F 'flowTools';M 'DisposeFlowTools'|Out-Null;$flow.Clear();$tools=@();foreach($entry in @(@('ImageSource','01 Input'),@('ImageFilter','02 Filter'),@('ImageEnhancement','03 Enhance'),@('ImageMirror','04 Mirror'),@('ImageRotate','05 Rotate'),@('ImageThreshold','06 Segment'),@('RegionContourMeasurement','07 Contour'),@('XldCircleFitting','08 Fit'),@('NumericJudge','09 Judge'),@('TextAssembly','10 Message'))){$t=Tool $entry[0] $entry[1];$flow.Add($t);$tools+=$t}
  $tools[1].SetInputBinding('Image',$tools[0].ToolId,'Image');$tools[2].SetInputBinding('Image',$tools[1].ToolId,'Image');$tools[3].SetInputBinding('Image',$tools[2].ToolId,'Image');$tools[4].SetInputBinding('Image',$tools[3].ToolId,'Image');$tools[5].SetInputBinding('Image',$tools[4].ToolId,'Image');$tools[6].SetInputBinding('Region',$tools[5].ToolId,'Region');$tools[7].SetInputBinding('XLD',$tools[6].ToolId,'XLD');$tools[8].SetInputBinding('Value',$tools[7].ToolId,'Radius');$tools[9].SetInputBinding('Number',$tools[7].ToolId,'Radius')
  (F 'FlowToolList').SelectedItem=$tools[4];M 'RefreshFlowGraphLayout'|Out-Null;Pump 300
  $xs=@($tools|Select-Object -ExpandProperty GraphX|Select-Object -Unique);$viewport=F 'FlowGraphViewport';$canvas=F 'FlowGraphCanvas';Assert ($xs.Count-eq1 -and @($tools|Where-Object{$_.GraphHeight-gt74.1}).Count-eq0) 'Automatic flow is not compact and vertical.'
  Assert ($viewport.ScrollableWidth-lt12) ('Automatic layout still forces horizontal scrolling: '+$viewport.ScrollableWidth)
  Assert ($canvas.Width*$((F 'FlowZoomSlider').Value)-le$viewport.ViewportWidth+12) 'Automatic canvas does not respond to the visible viewport.'
  $navigator=F 'flowNavigatorItemsS73';Assert ($navigator.Count-eq$flow.Count -and (F 'FlowNavigatorRailS73').Visibility.ToString()-eq'Visible') 'Thin long-flow navigator is missing real steps.'
  $tools[2].IsBreakpoint=$true;$tools[4].IsExecutionPointer=$true;$tools[7].ResultCode='NG';$tools[7].RunStatus='异常';M 'RefreshFlowGraphLayout'|Out-Null;Pump 100
  $tips=@($navigator|ForEach-Object{$_.ToolTip});$joinedTips=$tips -join ' | ';Write-Output ('S73_NAV_STATES='+$joinedTips);$navColors=@($navigator|ForEach-Object{$_.Fill.Color.ToString()});Assert (($navColors -contains '#FF8B5CF6') -and ($navColors -contains '#FFF59E0B') -and ($navColors -contains '#FFEF4444')) 'Navigator does not distinguish breakpoint/execution/NG states.'
  $realMarker=FindNavButton (F 'FlowNavigatorItemsS73') ([string]$tools[8].ToolId);Assert ($null-ne$realMarker) 'Navigator marker button was not realized.';$realMarker.RaiseEvent([Windows.RoutedEventArgs]::new([Windows.Controls.Button]::ClickEvent));Pump 120;$selectedAfterMarker=(F 'FlowToolList').SelectedItem;Write-Output ('S73_NAV_SELECTED='+$selectedAfterMarker.InstanceName);Assert ([object]::ReferenceEquals($selectedAfterMarker,$tools[8])) 'Navigator marker click did not locate its real module.'
  $manualField=$main.GetField('isManualFlowLayout',$private);M 'EnableManualFlowLayout'|Out-Null;$tools[0].GraphX=1200;$tools[0].GraphY=96;M 'RefreshFlowGraphLayout'|Out-Null;Pump 100;Assert ([Math]::Abs($tools[0].GraphX-1200)-lt0.1 -and $canvas.Width-gt1500) 'Responsive automatic layout overwrote manual graph coordinates.';$manualField.SetValue($window,$false)

  # B: Point2D[] -> real HALCON circle fit -> Circle2D/center/radius/residual/XLD and typed downstreams.
  M 'DisposeFlowTools'|Out-Null;$flow.Clear();$source=Tool 'CircularCaliperCircleFinder' 'Point Producer';$fit=Tool 'TypedPointSetCircleFittingMeasurement' 'Typed Circle Fit';$pointCarrier=Tool 'PointPairLineConstructionMeasurement' 'Point Carrier';$lineCarrier=Tool 'XldLineFitting' 'Line Carrier';$circleCarrier=Tool 'XldCircleFitting' 'Circle Carrier';$radial=Tool 'PointToCircleRadialDeviationMeasurement' 'Radial Check';$lineCircle=Tool 'LineCircleIntersectionMeasurement' 'Line Circle';$circleCircle=Tool 'CircleCircleIntersectionMeasurement' 'Circle Circle';$judge=Tool 'NumericJudge' 'Residual Judge';foreach($t in @($source,$fit,$pointCarrier,$lineCarrier,$circleCarrier,$radial,$lineCircle,$circleCircle,$judge)){$flow.Add($t)}
  $fit.SetInputBinding('Points',$source.ToolId,'EdgePoints');$radial.SetInputBinding('Point',$pointCarrier.ToolId,'MidPoint');$radial.SetInputBinding('Circle',$fit.ToolId,'MainCircle');$lineCircle.SetInputBinding('Line',$lineCarrier.ToolId,'MainLine');$lineCircle.SetInputBinding('Circle',$fit.ToolId,'MainCircle');$circleCircle.SetInputBinding('CircleA',$fit.ToolId,'MainCircle');$circleCircle.SetInputBinding('CircleB',$circleCarrier.ToolId,'MainCircle');$judge.SetInputBinding('Value',$fit.ToolId,'MaxResidual');$judge.InputToolId=$fit.ToolId;$judge.InputPortName='MaxResidual';$judge.NumericOperator='LessOrEqual';$judge.NumericUpperLimit=0.01
  $ctx='S73.Image';$rows=New-Object 'double[]' 36;$cols=New-Object 'double[]' 36;for($i=0;$i-lt36;$i++){$a=2*[Math]::PI*$i/36;$rows[$i]=50+30*[Math]::Sin($a);$cols[$i]=80+30*[Math]::Cos($a)};$source.SetOutputValue('EdgePoints',(Points $rows $cols $ctx));$source.ResultCode='OK';$fit.Parameters.PointSetMinimumCount=6;$fit.Parameters.XldCircleFitAlgorithm='atukey';$fit.Parameters.XldCircleFitIterations=10;$result=Run $fit
  $circle=Out $fit 'MainCircle';$center=Out $fit 'CenterPoint';$residual=[double](Out $fit 'MaxResidual');$xld=Out $fit 'XLD';Write-Output ('S73_TYPED_CIRCLE_FIT='+$result.ResultCode+'|'+$circle.ToDisplayString()+'|MaxResidual='+$residual+'|XLD='+$xld.ObjectCount)
  Assert (($result.ResultCode-eq'OK') -and $circle.CoordinateContextId-eq$ctx -and [Math]::Abs($circle.CenterRow-50)-lt0.05 -and [Math]::Abs($circle.CenterColumn-80)-lt0.05 -and [Math]::Abs($circle.Radius-30)-lt0.05 -and $residual-lt0.01 -and $xld.ObjectCount-eq74) 'HALCON typed point-set circle fit outputs are wrong.'
  Assert ($center.GetType()-eq$pointType -and [double](Out $fit 'ValidCount')-eq36 -and (Has $fit 'Radius')) 'Typed center/count/radius outputs are missing.'
  $pointCarrier.SetOutputValue('MidPoint',(Point 50 120 $ctx));$pointCarrier.ResultCode='OK';$lineCarrier.SetOutputValue('MainLine',(Line 50 0 50 160 $ctx));$lineCarrier.ResultCode='OK';$circleCarrier.SetOutputValue('MainCircle',(Circle 50 110 30 $ctx));$circleCarrier.ResultCode='OK';Assert ((Run $radial).ResultCode-eq'OK' -and (Run $lineCircle).ResultCode-eq'OK' -and (Run $circleCircle).ResultCode-eq'OK' -and (Run $judge).ResultCode-eq'OK') 'Circle2D/center/residual downstream chain failed.'
  $fit.Parameters.XldCircleFitAlgorithm='atukey';$outlierRows=[double[]]$rows.Clone();$outlierCols=[double[]]$cols.Clone();$outlierRows[12]+=12;$outlierCols[12]+=8;$source.SetOutputValue('EdgePoints',(Points $outlierRows $outlierCols $ctx));$source.ResultCode='OK';$robust=Run $fit;$robustCircle=Out $fit 'MainCircle';$robustResidual=[double](Out $fit 'MaxResidual');Assert (($robust.ResultCode-eq'OK') -and [Math]::Abs($robustCircle.Radius-30)-lt2 -and $robustResidual-gt5) 'ATukey circle fit did not preserve inliers or expose the outlier.'
  (F 'FlowToolList').SelectedItem=$fit;M 'LoadDockConfigurationDraft' ([object[]]@($fit))|Out-Null;Assert ((F 'DockTypedPointSetCircleFitPanel').Visibility.ToString()-eq'Visible' -and (F 'DockTypedPointSetCircleFitAlgorithmComboBox').SelectedValue-eq'atukey') 'Typed point-set circle parameters are not in the persistent dock.'
  M 'RefreshPortDataMonitorS64' ([object[]]@($fit))|Out-Null;Assert (@((F 'portDataMonitorRows')|Where-Object{$_.DataType-eq'Point2D[]' -or $_.DataType-eq'Circle2D'}).Count-ge2) 'I/O monitor did not expose Point2D[]/Circle2D ports.'
  $old=Out $fit 'XLD';$source.SetOutputValue('EdgePoints',(Points $rows $cols $ctx));$source.ResultCode='OK';Run $fit|Out-Null;Assert $old.IsDisposed 'Rerun did not dispose old managed XLD.'
  $fit.Parameters.PointSetMinimumCount=6;$fit.Parameters.PointSetAbnormalPolicy='SkipInvalid';$mixed=Points $rows $cols $ctx;$mixed.Points[3].IsValid=$false;$source.SetOutputValue('EdgePoints',$mixed);$source.ResultCode='OK';$skip=Run $fit;Assert (($skip.ResultCode-eq'NG') -and [double](Out $fit 'RejectedCount')-eq1 -and (Has $fit 'MainCircle')) 'SkipInvalid circle-fit semantics failed.'
  $fit.Parameters.PointSetAbnormalPolicy='Reject';$failed=$false;try{Run $fit|Out-Null}catch{$failed=$true};Assert $failed 'Reject policy accepted an invalid point.'
  $fit.Parameters.PointSetAbnormalPolicy='SkipInvalid';$cross=Points ([double[]](20,30,40,50,60,70)) ([double[]](40,50,60,70,80,90)) $ctx;$cross.Points[1].CoordinateContextId='Other.Image';$source.SetOutputValue('EdgePoints',$cross);$source.ResultCode='OK';$failed=$false;try{Run $fit|Out-Null}catch{$failed=$true};Assert $failed 'Mixed coordinate contexts were accepted.'
  $source.SetOutputValue('EdgePoints',(Points ([double[]](1,1,1,1,1,1)) ([double[]](2,2,2,2,2,2)) $ctx));$source.ResultCode='OK';$failed=$false;try{Run $fit|Out-Null}catch{$failed=$true};Assert $failed 'Coincident point set was accepted.'
  $source.SetOutputValue('EdgePoints',(Points ([double[]](1,2,3,4,5,6)) ([double[]](2,4,6,8,10,12)) $ctx));$source.ResultCode='OK';$failed=$false;try{Run $fit|Out-Null}catch{$failed=$true};Assert $failed 'Near-collinear point set was accepted.'
  $source.SetOutputValue('EdgePoints',(Points $rows $cols $ctx));$source.ResultCode='--';$failed=$false;try{Run $fit|Out-Null}catch{$failed=$true};Assert $failed 'Stale/unrun Point2D[] source was accepted.'
  $source.ResultCode='OK';$fit.Parameters.PointSetAbnormalPolicy='Reject';$recipe=M 'CaptureRecipe';$saved=$recipe.ToolFlow|Where-Object ToolId -eq $fit.ToolId|Select-Object -First 1;Assert ($saved.Parameters.XldCircleFitAlgorithm-eq'atukey' -and $saved.Parameters.PointSetMinimumCount-eq6) 'Recipe lost typed point-set circle parameters.'
  SelectTools @($source,$fit);$copied=[int](M 'CopySelectedFlowToolsToClipboard');$pasted=[int](M 'PasteFlowToolClipboard' ([object[]]@($flow.Count)));$copyBlock=@($flow|Select-Object -Last 2);$copyFit=$copyBlock|Where-Object{$_.Kind.ToString()-eq'TypedPointSetCircleFittingMeasurement'}|Select-Object -First 1;Assert (($copied-eq2)-and($pasted-eq2)-and$copyFit.GetInputBinding('Points').SourceToolId-eq$copyBlock[0].ToolId) 'Typed circle-fit block copy did not remap Points source.'
  Write-Output 'S73 responsive vertical canvas/thin navigator/manual-layout preservation + HALCON typed Point2D[] circle fitting/downstreams/dock/I-O/recipe/copy/lifecycle/failures passed; BSB not implemented.'
}finally{$main.GetField('recipeCloseConfirmed',$private).SetValue($window,$true);$window.Close();if($ownsApp){$app.Shutdown()};if(Test-Path $temp){Remove-Item -LiteralPath $temp -Recurse -Force}}
